import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { TwitterApi } from 'twitter-api-v2';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const client = new TwitterApi({
  appKey: process.env.TWITTER_API_KEY ?? '',
  appSecret: process.env.TWITTER_API_SECRET ?? '',
  accessToken: process.env.TWITTER_ACCESS_TOKEN ?? '',
  accessSecret: process.env.TWITTER_ACCESS_SECRET ?? '',
});
const receiptFile = 'x-post.json';
const text = 'The Model Editor opens a .blend in the browser: Blender 5.2, compiled to WebAssembly.';
const me = await client.v2.me();
if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receiptFile, 'utf8'));
  assert.equal(me.data.id, saved.account);
  const post = await client.v2.singleTweet(saved.post, { 'tweet.fields': ['author_id', 'created_at'] });
  assert.equal(post.data.text, text);
  assert.equal(post.data.author_id, saved.account);
  assert.equal(post.data.created_at, saved.created_at);
  const timeline = await client.v2.userTimeline(me.data.id, { max_results: 5 });
  assert.deepEqual(timeline.tweets.map((t) => t.id), [saved.post]);
  console.log(JSON.stringify({ retained: true, ...saved }));
} else {
  assert.ok(/^\d+$/.test(me.data.id) && me.data.username, 'v2.me answered ' + JSON.stringify(me));
  const made = await client.v2.tweet(text);
  assert.ok(/^\d+$/.test(made.data.id), 'v2.tweet answered ' + JSON.stringify(made));
  assert.equal(made.data.text, text);
  const post = await client.v2.singleTweet(made.data.id, { 'tweet.fields': ['author_id', 'created_at'] });
  assert.equal(post.data.text, text);
  assert.equal(post.data.author_id, me.data.id);
  assert.ok(post.data.created_at, 'the post reads back no created_at');
  const timeline = await client.v2.userTimeline(me.data.id, { max_results: 5 });
  assert.deepEqual(timeline.tweets.map((t) => t.id), [made.data.id]);
  const saved = { account: me.data.id, username: me.data.username, post: made.data.id, created_at: post.data.created_at };
  writeFileSync(receiptFile, JSON.stringify(saved) + '\n');
  console.log(JSON.stringify({ posted: true, ...saved }));
}
